def minPath(grid, k):
    from heapq import heappush, heappop

    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Priority queue: (current_path, row, col)
    heap = []

    # Initialize the heap with all possible starting positions
    for i in range(N):
        for j in range(N):
            path = [grid[i][j]]
            heappush(heap, (path, i, j))

    # To keep track of visited states (path, position)
    visited = set()

    while heap:
        path, i, j = heappop(heap)
        if len(path) == k:
            return path
        state = (tuple(path), i, j)
        if state in visited:
            continue
        visited.add(state)

        for dx, dy in directions:
            ni, nj = i + dx, j + dy
            if 0 <= ni < N and 0 <= nj < N:
                new_path = path + [grid[ni][nj]]
                heappush(heap, (new_path, ni, nj))

